// S646 — Katalogo mu-plugin diegimas su automatiniu atkurimu
const USER=process.env.WP_USER.trim(),PASS=process.env.WP_APP_PASS.trim();
const AUTH='Basic '+Buffer.from(USER+':'+PASS).toString('base64');
const BASE='https://dev.avesa.lt/wp-json/code-snippets/v1/snippets';
const TOK=process.env.GH_TOKEN;
process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const D='';
async function putResult(n,o){
  const url='https://api.github.com/repos/raimis079-creator/petshop-bridge/contents/screenshots/'+n;
  let sha;const g=await fetch(url,{headers:{Authorization:'Bearer '+TOK}});
  if(g.status===200) sha=(await g.json()).sha;
  const b={message:'r '+n,content:Buffer.from(JSON.stringify(o,null,1)).toString('base64')}; if(sha)b.sha=sha;
  const r=await fetch(url,{method:'PUT',headers:{Authorization:'Bearer '+TOK,'Content-Type':'application/json'},body:JSON.stringify(b)});
  console.log('putResult',n,r.status);
}
async function putFile(p,buf,m){
  const url='https://api.github.com/repos/raimis079-creator/petshop-bridge/contents/'+p;
  let sha;const g=await fetch(url,{headers:{Authorization:'Bearer '+TOK}});
  if(g.status===200) sha=(await g.json()).sha;
  const b={message:m,content:buf.toString('base64')}; if(sha)b.sha=sha;
  const r=await fetch(url,{method:'PUT',headers:{Authorization:'Bearer '+TOK,'Content-Type':'application/json'},body:JSON.stringify(b)});
  console.log('putFile',p,r.status);
}
async function sveikata(){
  const o={};
  for(const [n,u] of [['shop','https://dev.avesa.lt/parduotuve/'],['home','https://dev.avesa.lt/'],
                      ['admin','https://dev.avesa.lt/wp-admin/'],['wc','https://dev.avesa.lt/wp-admin/edit.php?post_type=product']]){
    try{const r=await fetch(u+(u.includes('?')?'&':'?')+'cb='+Date.now(),{headers:{Authorization:AUTH,'User-Agent':'Mozilla/5.0'}});
      const t=await r.text(); o[n]={http:r.status,len:t.length,fatal:/Fatal error|Parse error/i.test(t)};
    }catch(e){o[n]={err:String(e)};}
  }
  return o;
}
const out={version:'S646-V1',errors:[]};
out.sveikata_pries=await sveikata();
let id=null;
try{
  const r=await fetch(BASE,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name:'TEMP Katalogo Diegejas (S646)',code:Buffer.from(D,'base64').toString('utf8'),scope:'global',active:true,priority:11})});
  const j=await r.json(); id=j.id; out.diegejas=j.id;
}catch(e){out.errors.push(String(e));}
if(id){
  await new Promise(x=>setTimeout(x,3000));
  try{
    const rr=await fetch('https://dev.avesa.lt/?ps_kat_deploy=D646x&k=ps2026&cb='+Date.now(),{headers:{'User-Agent':'Mozilla/5.0'}});
    const t=await rr.text();
    try{out.deploy=JSON.parse(t);}catch(e){out.deploy_raw=t.slice(0,1500);}
  }catch(e){out.errors.push(String(e));}
  await fetch(BASE+'/'+id,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})});
  await new Promise(x=>setTimeout(x,4000));
  out.sveikata_po=await sveikata();
  out.ok=Object.values(out.sveikata_po).every(v=>v.http===200&&!v.fatal);
}
// KATALOGO PUSLAPIS
if(out.ok){
  try{
    const t0=Date.now();
    const r=await fetch('https://dev.avesa.lt/wp-admin/admin.php?page=ps-katalogas&cb='+Date.now(),{headers:{Authorization:AUTH,'User-Agent':'Mozilla/5.0'}});
    const t=await r.text();
    out.katalogas={http:r.status,ms:Date.now()-t0,len:t.length,fatal:/Fatal error|Parse error/i.test(t),
      eiluciu:(t.match(/<tr>/g)||[]).length, rail:(t.match(/pskat-view/g)||[]).length,
      klaida:(t.match(/Warning:[^<]{0,120}/g)||[]).slice(0,5)};
  }catch(e){out.errors.push({s:'kat',e:String(e)});}
  // ekranas
  try{
    const {chromium}=await import('playwright');
    const br=await chromium.launch();
    const ctx=await br.newContext({viewport:{width:1600,height:1100},ignoreHTTPSErrors:true,
      httpCredentials:{username:USER,password:PASS}});
    const pg=await ctx.newPage();
    const errs=[]; pg.on('pageerror',e=>errs.push(String(e)));
    await pg.goto('https://dev.avesa.lt/wp-admin/admin.php?page=ps-katalogas',{waitUntil:'domcontentloaded',timeout:90000});
    await pg.waitForTimeout(3000);
    await putFile('screenshots/s646_katalogas.png', await pg.screenshot({fullPage:false}), 'S646 katalogas');
    out.shot={js:errs, url:pg.url(),
      prekiu: await pg.evaluate(()=>document.querySelectorAll('.pskat-t tbody tr').length),
      suvestine: await pg.evaluate(()=>Array.from(document.querySelectorAll('.pskat-suv .p')).map(e=>e.textContent.trim().replace(/\s+/g,' '))),
      eiles: await pg.evaluate(()=>Array.from(document.querySelectorAll('.pskat-view')).map(e=>e.textContent.trim().replace(/\s+/g,' ')))};
    await br.close();
  }catch(e){out.errors.push({s:'shot',e:String(e)});}
} else {
  out.GRIZIMAS='sveikata bloga po diegimo';
}
await putResult('s646_v1.json',out);
console.log('DONE');
